<?php $owner = can('team.manage'); ?>
<div class="top"><div><h2 style="margin:0">Team &amp; roles</h2><span class="muted"><?= (int) $customers ?> customers on record</span></div></div>
<?php if ($link): ?><div class="card mb"><h3>Password-setup link (shown once)</h3><p class="muted">Send this to the new person if the email does not arrive. Valid 2 hours; treat it as a secret.</p><input readonly value="<?= e($link) ?>"></div><?php endif; ?>
<?php if (!empty($reqs)): ?><div class="card mb"><h3>Admin removal waiting for agreement</h3><p class="muted">An admin can only be removed when every admin, including that person, agrees.</p>
<?php foreach ($reqs as $r): $mine = $r['votes'][$u['id']] ?? null; ?><div class="comment"><b><?= e($r['tname']) ?></b> <span class="muted">(<?= e($r['temail']) ?>) &middot; asked by <?= e($r['bname']) ?> &middot; <?= e(fmt_dt($r['created_at'])) ?></span><br>
<span class="who">Agreed: <?= e(implode(', ', array_map(fn($a) => $a['name'], array_filter($admins, fn($a) => ($r['votes'][$a['id']] ?? '') === 'approve'))) ?: 'nobody') ?> &middot; Still to decide: <?= e(implode(', ', array_map(fn($a) => $a['name'], array_filter($admins, fn($a) => !isset($r['votes'][$a['id']])))) ?: 'nobody') ?></span>
<?php if ($owner): ?><form method="post" action="/staff/team/requests/<?= (int) $r['id'] ?>" class="inline mt"><?= csrf_field() ?>
<?php if ($mine !== 'approve'): ?><button class="btn sm" name="decision" value="approve">Agree</button> <?php endif; ?><button class="btn sm alt" name="decision" value="reject">Reject</button>
<?php if ((int) $r['requested_by'] === (int) $u['id']): ?><button class="btn sm alt" name="decision" value="cancel">Cancel request</button><?php endif; ?></form><?php endif; ?></div><?php endforeach; ?></div><?php endif; ?>
<div class="card mb"><h3>People</h3><div class="tw"><table><tr><th>Name</th><th>Email</th><th>Role</th><th>Open tasks</th><th>Active</th><th></th></tr>
<?php foreach ($people as $p): ?>
<?php if ($owner && $p['role'] === 'owner' && $p['active'] && (int) $p['id'] !== (int) $u['id']): ?><tr><td><?= e($p['name']) ?></td><td><?= e($p['email']) ?></td><td><?= e(ROLES['owner']) ?></td><td><a href="/staff/tasks?who=<?= (int) $p['id'] ?>"><?= (int) $p['open_tasks'] ?></a></td><td>Yes</td>
<td><a class="btn sm alt" href="/staff/team/<?= (int) $p['id'] ?>/profile">Details</a> <form method="post" action="/staff/team/<?= (int) $p['id'] ?>/removal" class="inline"><?= csrf_field() ?><button class="btn sm alt" data-confirm="Ask all admins to agree to remove this admin?">Request removal</button></form></td></tr>
<?php elseif ($owner && !$p['active']): ?><tr style="opacity:.8"><td><?= e($p['name']) ?></td><td><?= e($p['email']) ?></td><td><?= e(ROLES[$p['role']]) ?></td><td>-</td><td><?= $p['frozen'] ? badge('Frozen', 'p-warn') : badge('Removed') ?></td>
<td style="white-space:normal"><a class="btn sm alt" href="/staff/team/<?= (int) $p['id'] ?>/profile">Details</a>
<?php if ($p['frozen']): ?> <form method="post" action="/staff/team/<?= (int) $p['id'] ?>/unfreeze" class="inline"><?= csrf_field() ?><button class="btn sm" data-confirm="Unfreeze <?= e($p['name']) ?>? They can sign in again as before.">Unfreeze</button></form>
<form method="post" action="/staff/team/<?= (int) $p['id'] ?>/remove" class="inline"><?= csrf_field() ?><button class="btn sm danger" data-confirm="Remove <?= e($p['name']) ?> from the team?">Remove</button></form>

<?php else: ?> <form method="post" action="/staff/team/<?= (int) $p['id'] ?>/restore" class="inline"><?= csrf_field() ?><button class="btn sm alt" data-confirm="Bring <?= e($p['name']) ?> back? A new password link is created.">Restore</button></form>
<?php if ($p['role'] !== 'owner'): ?><details style="display:block;margin-top:6px"><summary class="btn sm danger" style="display:inline-block;list-style:none;cursor:pointer">Delete permanently</summary>
<form method="post" action="/staff/team/<?= (int) $p['id'] ?>/delete" style="margin-top:6px;max-width:320px"><?= csrf_field() ?><p class="muted" style="margin:0 0 4px;font-size:.82rem;white-space:normal">Cannot be undone. Erases <?= e($p['name']) ?>'s details, files and private notes; their past work stays without their name. Type your password and <b><?= e($p['email']) ?></b> to confirm.</p><input name="current" type="password" autocomplete="current-password" placeholder="Your password" aria-label="Your password" style="margin:0 0 4px"><input name="confirm" autocomplete="off" placeholder="Their e-mail address" aria-label="Their e-mail address" style="margin:0 0 4px"><button class="btn sm danger" data-confirm="Delete <?= e($p['name']) ?> permanently? This cannot be undone.">Delete permanently</button></form></details><?php endif; ?>
<?php endif; ?></td></tr>
<?php elseif ($owner): $fid = 'tf' . (int) $p['id']; ?><tr><td><?= avatar_tag($p, 26) ?> <?= e($p['name']) ?><form id="<?= $fid ?>" method="post" action="/staff/team/<?= (int) $p['id'] ?>"><?= csrf_field() ?><input type="hidden" name="active" value="1"></form></td><td><?= e($p['email']) ?></td>
<td><select name="role" form="<?= $fid ?>" style="margin:0"><?= options(ROLES, $p['role']) ?></select></td><td><a href="/staff/tasks?who=<?= (int) $p['id'] ?>"><?= (int) $p['open_tasks'] ?></a></td><td>Yes</td>
<td style="white-space:nowrap"><a class="btn sm alt" href="/staff/team/<?= (int) $p['id'] ?>/profile">Details</a> <button form="<?= $fid ?>" class="btn sm alt">Save</button><?php if ($p['role'] !== 'owner' && !empty($p['totp_enabled'])): ?> <form method="post" action="/staff/team/<?= (int) $p['id'] ?>/reset2fa" class="inline"><?= csrf_field() ?><button class="btn sm alt" data-confirm="Turn off two-factor login for <?= e($p['name']) ?>?">Reset 2FA</button></form><?php endif; ?>
<?php if ($p['role'] !== 'owner' && (int) $p['id'] !== (int) $u['id']): ?> <form method="post" action="/staff/team/<?= (int) $p['id'] ?>/freeze" class="inline"><?= csrf_field() ?><button class="btn sm alt" data-confirm="Freeze <?= e($p['name']) ?>? They cannot sign in until you unfreeze them; nothing else changes.">Freeze</button></form> <form method="post" action="/staff/team/<?= (int) $p['id'] ?>/remove" class="inline"><?= csrf_field() ?><button class="btn sm danger" data-confirm="Remove <?= e($p['name']) ?> from the team? They can no longer sign in and their open tasks become unassigned.">Remove</button></form><?php endif; ?>
<?php if ($p['role'] !== 'owner' && (int) $p['id'] !== (int) $u['id']): ?><?php endif; ?></td></tr>
<?php else: ?><tr><td><?= e($p['name']) ?></td><td><?= e($p['email']) ?></td><td><?= e(ROLES[$p['role']]) ?></td><td><?= (int) $p['open_tasks'] ?></td><td><?= $p['active'] ? 'Yes' : 'No' ?></td><td></td></tr><?php endif; ?>
<?php endforeach; ?></table></div></div>
<div class="grid g2" style="align-items:start">
<div class="card"><h3>What each role can do</h3><dl class="kv"><?php foreach (ROLES as $k => $l): ?><dt><?= e($l) ?></dt><dd><?= e(ROLE_DESC[$k]) ?></dd><?php endforeach; ?></dl>
